180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
183	        Collection<Owner> owners;
184	        if (lastName != null) {
185	            owners = this.clinicService.findOwnerByLastName(lastName);
186	        } else {
187	            owners = this.clinicService.findAllOwners();
188	        }
189	        if (owners.isEmpty()) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
193	    }
