195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
203	    }
