205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
208	        String idempotencyKey = idempotencyKey();
209	        ResponseEntity<OwnerDto> replay = replayIfDuplicateKey(idempotencyKey);
210	        if (replay != null) {
211	            return replay;
212	        }
213	        addressResolver.resolve(ownerFieldsDto);
214	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
215	        if (!missingFields.isEmpty()) {
216	            throw new MissingOwnerFieldsException(missingFields);
217	        }
218	        HttpHeaders headers = new HttpHeaders();
219	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
220	        Collection<Owner> sameLastName =
221	            activeOwners(this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName()));
222	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
223	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
224	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
225	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
226	        disposableEmailDomainValidator.validate(owner.getEmail());
227	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
228	        rejectIfDuplicateIdentity(owner);
229	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
230	        registrationDateValidator.validate(owner.getRegistrationDate());
231	        if (owner.getRegistrationDate() == null) {
232	            owner.setRegistrationDate(LocalDate.now());
233	        }
234	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
235	        LocalDate registrationDate = owner.getRegistrationDate();
236	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
237	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
238	            throw new DailyOwnerLimitException(registrationDate);
239	        }
240	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
241	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
242	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
243	            throw new CityOwnerLimitException(owner.getCity());
244	        }
245	        owner.setCapacityWarning(cityCapacityWarningEvaluator.isApproachingCapacity(cityOwnerCount));
246	        owner.setMemberId(assignMemberId(owner));
247	        this.clinicService.saveOwner(owner);
248	        if (idempotencyKey != null) {
249	            idempotencyStore.record(idempotencyKey, owner.getId());
250	        }
251	        ownerAuditLogger.ownerCreated(owner);
252	        welcomeNotifier.welcome(owner);
253	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
254	        headers.setLocation(UriComponentsBuilder.newInstance()
255	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
256	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
257	    }
258	
259	    /**
260	     * Reads the request's {@code Idempotency-Key} header, treating a blank value as absent.
261	     *
262	     * @return the trimmed key, or {@code null} when the request carries no usable key
263	     */
264	    private String idempotencyKey() {
265	        String key = request.getHeader("Idempotency-Key");
266	        return StringUtils.hasText(key) ? key.trim() : null;
267	    }
268	
269	    /**
270	     * Replays the owner originally created for an already-seen idempotency key, so a repeated
271	     * create returns that owner with 200 instead of storing a duplicate. Returns {@code null}
272	     * when there is no key or the key has not been seen, in which case the create proceeds
273	     * normally.
274	     */
275	    private ResponseEntity<OwnerDto> replayIfDuplicateKey(String idempotencyKey) {
276	        if (idempotencyKey == null) {
277	            return null;
278	        }
279	        return idempotencyStore.find(idempotencyKey)
280	            .map(clinicService::findOwnerById)
281	            .map(ownerMapper::toOwnerDto)
282	            .map(ownerDto -> new ResponseEntity<>(ownerDto, HttpStatus.OK))
283	            .orElse(null);
284	    }
285	
286	    /**
287	     * Assigns the household attributes of an owner about to be created, without touching any
288	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
289	     * name and postcode, so every owner in the same household shares it automatically regardless of
290	     * creation order. The new owner's household size after this create is recorded: the existing
291	     * members that share its household (same last name and postcode) plus the owner itself.
292	     *
293	     * @return the existing members of the owner's household (empty when it starts a new household)
294	     */
295	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
296	        owner.setHouseholdId(householdIdGenerator.generate(owner));
297	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
298	        owner.setHouseholdSize(members.size() + 1);
299	        return members;
300	    }
301	
302	    /**
303	     * Computes the member id for an owner about to be created, de-duplicated against the ids already
304	     * assigned to existing owners so that distinct owners always receive distinct ids.
305	     *
306	     * @return the owner's unique member id
307	     */
308	    private String assignMemberId(Owner owner) {
309	        String region = OwnerIdentityVersion.tag(
310	            LocalityResolver.localityOf(owner.getPostcode(), owner.getCity()));
311	        String baseId = memberIdGenerator.generate(
312	            region, owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName());
313	        List<String> takenIds = clinicService.findOwnersByMemberIdStartingWith(baseId)
314	            .stream()
315	            .map(Owner::getMemberId)
316	            .toList();
317	        return memberIdGenerator.deduplicate(baseId, takenIds);
318	    }
319	
320	    /**
321	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
322	     * When the owner joins an existing household (same last name and postcode) its membership level
323	     * is capped to at most one above the highest level among the existing members. A member declared
324	     * with {@code sharesHousehold} is, being knowingly registered, not treated as a suspected
325	     * duplicate; an undeclared one still runs the ordinary possible-duplicate detection. When the
326	     * owner starts a new household no cap applies and possible-duplicate detection runs as usual.
327	     */
328	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
329	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
330	        if (householdMembers.isEmpty()) {
331	            flagPossibleDuplicate(owner, sameLastName);
332	            return;
333	        }
334	        owner.setMembershipLevelCap(MembershipLevelCalculator.householdLevelCeiling(householdMembers));
335	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
336	            owner.setPossibleDuplicate(false);
337	            owner.setPossibleDuplicateOf(null);
338	        } else {
339	            flagPossibleDuplicate(owner, sameLastName);
340	        }
341	    }
342	
343	    /**
344	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
345	     * owner. A full-key match requires an equal telephone, so only owners with the same
346	     * (already normalized) telephone are compared.
347	     *
348	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
349	     */
350	    private void rejectIfDuplicateIdentity(Owner owner) {
351	        Collection<Owner> sameTelephone =
352	            activeOwners(this.clinicService.findOwnersByTelephone(owner.getTelephone()));
353	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
354	            throw new DuplicateIdentityException(IdentityKey.of(owner));
355	        }
356	    }
357	
358	    /**
359	     * Filters out soft-deleted owners, so the create endpoint's duplicate and identity checks
360	     * consider only owners that are still active. A soft-deleted owner keeps its row but is
361	     * treated as absent for the purpose of detecting duplicates of a newly created owner.
362	     */
363	    private List<Owner> activeOwners(Collection<Owner> owners) {
364	        return owners.stream().filter(candidate -> !candidate.isDeleted()).toList();
365	    }
366	
367	    /**
368	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
369	     * existing owner's last name and postcode with a different telephone. The matching owner's id
370	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
371	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
372	     * seen here is guaranteed not to be a hard duplicate.
373	     */
374	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
375	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
376	        owner.setPossibleDuplicate(match != null);
377	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
378	    }
