380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Override
382	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
383	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
384	        if (currentOwner == null) {
385	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
386	        }
387	        currentOwner.setAddress(ownerFieldsDto.getAddress());
388	        currentOwner.setCity(ownerFieldsDto.getCity());
389	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
390	        currentOwner.setLastName(ownerFieldsDto.getLastName());
391	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
392	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
393	        this.clinicService.saveOwner(currentOwner);
394	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
395	    }
396	
397	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
398	    @Transactional
399	    @Override
400	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
401	        Owner owner = this.clinicService.findOwnerById(ownerId);
402	        if (owner == null) {
403	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
404	        }
405	        owner.setDeleted(true);
406	        this.clinicService.saveOwner(owner);
407	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
408	    }
409	
410	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
411	    @Override
412	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
413	        Owner owner = this.clinicService.findOwnerById(ownerId);
414	        if (owner == null) {
415	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
416	        }
417	        HttpHeaders headers = new HttpHeaders();
418	        Pet pet = petMapper.toPet(petFieldsDto);
419	        owner.setId(ownerId);
420	        pet.setOwner(owner);
421	        pet.getType().setName(null);
422	        this.clinicService.savePet(pet);
423	        PetDto petDto = petMapper.toPetDto(pet);
424	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
425	            .buildAndExpand(pet.getId()).toUri());
426	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
427	    }
428	
429	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
430	    @Override
431	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
432	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
433	        if (currentOwner != null) {
434	            Pet currentPet = this.clinicService.findPetById(petId);
435	            if (currentPet != null) {
436	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
437	                currentPet.setName(petFieldsDto.getName());
438	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
439	                this.clinicService.savePet(currentPet);
440	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
441	            }
442	        }
443	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
444	    }
