446	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
447	    @Override
448	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
449	        HttpHeaders headers = new HttpHeaders();
450	        Visit visit = visitMapper.toVisit(visitFieldsDto);
451	        Pet pet = new Pet();
452	        pet.setId(petId);
453	        visit.setPet(pet);
454	        this.clinicService.saveVisit(visit);
455	        VisitDto visitDto = visitMapper.toVisitDto(visit);
456	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
457	            .buildAndExpand(visit.getId()).toUri());
458	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
459	    }
460	
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Override
464	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
465	        Owner owner = this.clinicService.findOwnerById(ownerId);
466	        if (owner != null) {
467	            Pet pet = owner.getPet(petId);
468	            if (pet != null) {
469	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
470	            }
471	        }
472	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
473	    }
474	}
